  lemurienTiki: { element: 'feuille', demi: true, nom: 'Lémurien Tiki', modele: 'lemurien', icone: 'lemurien-tiki', desc: 'le sorcier masqué, bête sauvage et incantateur vaudou : son fouet de queue te repousse (sors de l\'arc bleu), sa toupie de queue frappe tout autour de lui (sors du cercle bleu), il bondit sur toi (sors du cercle rouge) ; il plante des totems-masques qui crachent des fléchettes (casse-les), danse avec ses masques pour aller plus vite, et te maudit : un masque fantôme te suit puis tombe (sors du cercle dès qu\'il s\'arrête : s\'il te touche, tu es maudit 2 s sans pouvoir bouger) ; enragé sous 30 % de vie', res: 'couenne', pv: () => pvBoss(9) / 2, deg: () => 30, cadence: 1.3, vitesse: 2.7, portee: 2.0, ombre: 1.8, armure: 0.1, brassard: 6, brassardNom: 'lève sa queue pour fouetter', brassardTitre: 'Fouet de queue', brassardCoup: 'un grand coup de queue', repousse: 3 * S, seisme: 9, seismeNom: 'Toupie de queue', seismeR: 3.4, seismeDuree: 1.2, seismeProche: 1.5, bondit: 8, degSort: 8, totems: { periode: 16, n: 3, R: 3.4 }, danse: { periode: 20, duree: 5, n: 5, vit: 1.5 }, malediction: { periode: 12, duree: 3.0, R: 2.0, prepa: 0.9, x: 1.2, maudit: 2 }, gestes: { brassard: 'fouet', seisme: 'toupie', totems: 'rugir', danse: 'rugir', malediction: 'rugir' }, rage: true, boss: true },
